    // -------------------------------------------------------------------------
    // Custom camera controls: orbit, pan, zoom, keyboard, and touch
    // -------------------------------------------------------------------------

    const controls = {
      theta: 0.72,
      phi: 1.0,
      radius: 48,
      target: new THREE.Vector3(0, 3.1, 0)
    };

    const cameraSpherical = new THREE.Spherical();

    function updateCamera() {
      cameraSpherical.set(
        controls.radius,
        controls.phi,
        controls.theta
      );
      camera.position.setFromSpherical(cameraSpherical).add(controls.target);
      camera.lookAt(controls.target);
    }

    function resetView() {
      controls.theta = 0.72;
      controls.phi = 1.0;
      controls.radius = 48;
      controls.target.set(0, 3.1, 0);
      updateCamera();
    }

    const canvas = renderer.domElement;
    const activePointers = new Map();
    let dragging = false;
    let lastX = 0;
    let lastY = 0;
    let lastPinchDistance = 0;
    let activePointerId = null;

    function pointerDistance() {
      const points = [...activePointers.values()];
      if (points.length < 2) return 0;
      return Math.hypot(
        points[0].x - points[1].x,
        points[0].y - points[1].y
      );
    }

    canvas.addEventListener("contextmenu", (event) => {
      event.preventDefault();
    });

    canvas.addEventListener("pointerdown", (event) => {
      canvas.setPointerCapture(event.pointerId);
      activePointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      if (activePointers.size === 1) {
        dragging = true;
        activePointerId = event.pointerId;
        lastX = event.clientX;
        lastY = event.clientY;
      } else if (activePointers.size === 2) {
        dragging = false;
        lastPinchDistance = pointerDistance();
      }
    });

    canvas.addEventListener("pointermove", (event) => {
      if (!activePointers.has(event.pointerId)) return;

      activePointers.set(event.pointerId, {
        x: event.clientX,
        y: event.clientY
      });

      if (activePointers.size === 2) {
        const distance = pointerDistance();
        if (lastPinchDistance > 0 && distance > 0) {
          controls.radius = THREE.MathUtils.clamp(
            controls.radius * (lastPinchDistance / distance),
            17,
            92
          );
          updateCamera();
        }
        lastPinchDistance = distance;
        return;
      }

      if (!dragging || event.pointerId !== activePointerId) return;

      const dx = event.clientX - lastX;
      const dy = event.clientY - lastY;
      lastX = event.clientX;
      lastY = event.clientY;

      if (event.shiftKey || event.buttons === 2) {
        const forward = new THREE.Vector3();
        camera.getWorldDirection(forward);
        forward.y = 0;
        forward.normalize();

        const right = new THREE.Vector3()
          .crossVectors(forward, new THREE.Vector3(0, 1, 0))
          .normalize();

        const panScale = controls.radius * 0.0013;
        controls.target.addScaledVector(right, -dx * panScale);
        controls.target.addScaledVector(forward, dy * panScale);

        controls.target.x = THREE.MathUtils.clamp(
          controls.target.x,
          -36,
          36
        );
        controls.target.z = THREE.MathUtils.clamp(
          controls.target.z,
          -32,
          32
        );
        controls.target.y = THREE.MathUtils.clamp(
          controls.target.y,
          0.5,
          13
        );
      } else {
        controls.theta -= dx * 0.006;
        controls.phi = THREE.MathUtils.clamp(
          controls.phi + dy * 0.005,
          0.24,
          1.46
        );
      }

      updateCamera();
    });

    function releasePointer(event) {
      activePointers.delete(event.pointerId);

      if (activePointers.size === 1) {
        const remaining = [...activePointers.entries()][0];
        activePointerId = remaining[0];
        lastX = remaining[1].x;
        lastY = remaining[1].y;
        dragging = true;
      } else {
        activePointerId = null;
        dragging = false;
        lastPinchDistance = 0;
      }
    }

    canvas.addEventListener("pointerup", releasePointer);
    canvas.addEventListener("pointercancel", releasePointer);

    canvas.addEventListener(
      "wheel",
      (event) => {
        event.preventDefault();
        controls.radius = THREE.MathUtils.clamp(
          controls.radius * Math.exp(event.deltaY * 0.001),
          17,
          92
        );
        updateCamera();
      },
      { passive: false }
    );

    window.addEventListener("keydown", (event) => {
      const key = event.key.toLowerCase();

      if (["arrowleft", "arrowright", "arrowup", "arrowdown"].includes(key)) {
        event.preventDefault();
      }

      if (key === "arrowleft") controls.theta += 0.08;
      if (key === "arrowright") controls.theta -= 0.08;
      if (key === "arrowup") controls.phi = Math.max(0.24, controls.phi - 0.06);
      if (key === "arrowdown") controls.phi = Math.min(1.46, controls.phi + 0.06);

      if (key === "w") {
        controls.target.z -= 0.7;
      }
      if (key === "s") {
        controls.target.z += 0.7;
      }
      if (key === "a") {
        controls.target.x -= 0.7;
      }
      if (key === "d") {
        controls.target.x += 0.7;
      }

      controls.target.x = THREE.MathUtils.clamp(
        controls.target.x,
        -36,
        36
      );
      controls.target.z = THREE.MathUtils.clamp(
        controls.target.z,
        -32,
        32
      );
      controls.target.y = THREE.MathUtils.clamp(
        controls.target.y,
        0.5,
        13
      );

      updateCamera();
    });

    document.getElementById("reset").addEventListener("click", resetView);

    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
      renderer.setSize(window.innerWidth, window.innerHeight);
    });

    // -------------------------------------------------------------------------
    // Render loop
    // -------------------------------------------------------------------------

    updateCamera();

    renderer.setAnimationLoop(() => {
      renderer.render(scene, camera);
    });

    requestAnimationFrame(() => {
      document.getElementById("loading").classList.add("hidden");
    });
  </script>
